233	fn parse_issue_create_output(stdout: &str) -> Option<(u64, Option<String>)> {
234	    // `gh issue create` prints the issue URL (e.g.
235	    // `https://github.com/owner/repo/issues/42`) on stdout. Extract the
236	    // trailing integer.
237	    let last_line = stdout.lines().last()?.trim();
238	    let number = last_line.rsplit('/').next()?.parse::<u64>().ok()?;
239	    let url = if last_line.starts_with("http") {
240	        Some(last_line.to_owned())
241	    } else {
242	        None
243	    };
244	    Some((number, url))
245	}
