247	fn parse_pr_list_output(stdout: &str) -> Result<Option<PrInfo>, CopilotDispatchError> {
248	    let value: Value =
249	        serde_json::from_str(stdout.trim()).map_err(|error| CopilotDispatchError::Parse {
250	            operation: "pr list".to_owned(),
251	            message: format!("json decode failed: {error}"),
252	        })?;
253	    let array = value
254	        .as_array()
255	        .ok_or_else(|| CopilotDispatchError::Parse {
256	            operation: "pr list".to_owned(),
257	            message: "expected top-level json array".to_owned(),
258	        })?;
259	    let Some(first) = array.first() else {
260	        return Ok(None);
261	    };
262	    let number =
263	        first
264	            .get("number")
265	            .and_then(Value::as_u64)
266	            .ok_or_else(|| CopilotDispatchError::Parse {
267	                operation: "pr list".to_owned(),
268	                message: "missing `number`".to_owned(),
269	            })?;
270	    let url = first
271	        .get("url")
272	        .and_then(Value::as_str)
273	        .ok_or_else(|| CopilotDispatchError::Parse {
274	            operation: "pr list".to_owned(),
275	            message: "missing `url`".to_owned(),
276	        })?
277	        .to_owned();
278	    let head_sha = first
279	        .get("headRefOid")
280	        .and_then(Value::as_str)
281	        .ok_or_else(|| CopilotDispatchError::Parse {
282	            operation: "pr list".to_owned(),
283	            message: "missing `headRefOid`".to_owned(),
284	        })?
285	        .to_owned();
286	    Ok(Some(PrInfo {
287	        number,
288	        url,
289	        head_sha,
