1	//! `CopilotHandDispatcher` — the real implementation of `HandDispatcher`
2	//! for the GitHub Copilot coding agent.
3	//!
4	//! The dispatcher takes ownership of the branch creation, issue creation,
5	//! Copilot assignment, substrate hand registration, and asynchronous PR
6	//! polling. See `T013` for the full design.
7	
8	use std::sync::Arc;
9	use std::time::Duration;
10	
11	use async_trait::async_trait;
12	use chrono::Utc;
13	use derrick_substrate::{
14	    EventKind, EventScope, Hand, HandId, HandKind, InReviewMetadata, Substrate, Ticket,
15	};
16	use derrick_substrate_native::foreman::{
17	    DispatchContext, DispatchError, DispatchResult, HandDispatcher,
18	};
19	use derrick_substrate_native::NativeSubstrate;
20	use tokio::time::Instant;
21	use tracing::{error, info, instrument, warn};
22	
23	use crate::branch::{branch_name, BranchCreator, BranchError};
24	use crate::client::{CopilotDispatchClient, CopilotDispatchError, PrInfo};
25	
26	/// Runtime configuration for [`CopilotHandDispatcher`]. Sourced from
27	/// `tools.copilot` in `derrick.yaml`.
28	#[derive(Clone, Debug)]
29	pub struct CopilotHandDispatcherConfig {
30	    /// Interval between successive PR polls. Default 30s.
31	    pub poll_interval: Duration,
32	    /// Maximum wall-clock duration the poll loop will wait for a PR before
33	    /// giving up. Default 10 minutes.
34	    pub poll_timeout: Duration,
35	    /// Branch name used as the base for new dispatch branches. Default
36	    /// `main`.
37	    pub base_branch: String,
38	    /// Stable identity prefix used when minting hand ids. The dispatcher
39	    /// appends a short random suffix so multiple dispatches do not collide.
40	    pub agent_identity: String,
41	    /// Prefix applied to dispatch branch names. Combined with the ticket
42	    /// batch and id to form `<prefix>/<batch>/<ticket-id>`. Sourced from
43	    /// `tools.git.branch_prefix`; defaults to `"derrick"`.
44	    pub branch_prefix: String,
45	    /// Whether to prepend Roughneck instructions to the issue body submitted
46	    /// to Copilot.
47	    pub roughneck_enabled: bool,
48	    /// Roughneck level: "lite", "full", or "ultra".
49	    pub roughneck_level: String,
50	}
51	
52	impl Default for CopilotHandDispatcherConfig {
53	    fn default() -> Self {
54	        Self {
55	            poll_interval: Duration::from_secs(30),
56	            poll_timeout: Duration::from_secs(60 * 10),
57	            base_branch: "main".to_owned(),
58	            agent_identity: "derrick-hand".to_owned(),
59	            branch_prefix: "derrick".to_owned(),
60	            roughneck_enabled: true,
61	            roughneck_level: "full".to_owned(),
62	        }
63	    }
64	}
65	
66	/// `HandDispatcher` for the GitHub Copilot coding agent. See module docs.
67	pub struct CopilotHandDispatcher {
68	    substrate: Arc<NativeSubstrate>,
69	    branch_creator: Arc<dyn BranchCreator>,
70	    client: Arc<dyn CopilotDispatchClient>,
71	    config: CopilotHandDispatcherConfig,
72	}
73	
74	impl CopilotHandDispatcher {
75	    /// Construct a dispatcher from its three collaborators and config.
76	    pub fn new(
77	        substrate: Arc<NativeSubstrate>,
78	        branch_creator: Arc<dyn BranchCreator>,
79	        client: Arc<dyn CopilotDispatchClient>,
80	        config: CopilotHandDispatcherConfig,
81	    ) -> Self {
82	        Self {
83	            substrate,
84	            branch_creator,
85	            client,
86	            config,
87	        }
88	    }
89	
90	    fn mint_hand_id(&self, _ticket: &Ticket) -> Result<HandId, derrick_substrate::SubstrateError> {
91	        // Substrate validator: ^[a-z][a-z0-9-]{0,63}$. We sanitize
92	        // `agent_identity` to keep just ASCII letters/digits/hyphens (lowered)
93	        // and ensure the first character is a letter. Then append the first
94	        // 8 hex chars of a fresh v4 uuid for entropy.
95	        let suffix: String = uuid::Uuid::new_v4()
96	            .as_simple()
97	            .to_string()
98	            .chars()
99	            .take(8)
100	            .collect();
101	        let mut cleaned: String = self
102	            .config
103	            .agent_identity
104	            .chars()
105	            .filter_map(|c| {
106	                if c.is_ascii_alphanumeric() {
107	                    Some(c.to_ascii_lowercase())
108	                } else if c == '-' {
109	                    Some('-')
110	                } else {
111	                    None
112	                }
113	            })
